  function pollenRouteView(value,growth){var n=pollenRouteNumber(value),p=pollenPoint(POLLEN_ROUTE[n-1],growth);p.n=n;return p;}
  function pollenDetail(detail,growth){if(!detail||!detail.pollenSite)return detail;var p=pollenPoint(detail.id,growth);return p?Object.assign({},detail,{at:p.at,view:p.view}):detail;}
