  var NUCLEUS_CHARGE_RMS_FM=5.4371;
  function nucleusViewValue(value){return value==='section'?'section':'whole';}
  function nucleusDepthValue(value){return typeof value==='number'&&isFinite(value)?clamp(Math.round(value),0,100):50;}
  function nucleusVisibleCounts(value){var cut=nucleusDepthValue(value)/100-.5,p=0,n=0;NUCLEUS_LAYOUT.forEach(function(v){if(v.at[2]-v.radius<cut){if(v.kind==='proton')p++;else n++;}});return {protons:p,neutrons:n,total:p+n};}
  var HYDROGEN_BOHR_PM=52.9177210544;
  function hydrogenViewValue(value){return value==='section'?'section':'cloud';}
