  // Cosmicflows-4 (2023) reconstructed basin and peculiar-velocity field.
  // Native coordinates are supergalactic Mpc/h. This display uses h = 0.75.
  var LANIAKEA_REFERENCE_MPC=4.9e24/3.085677581491367e22;
  var LANIAKEA_H=.75;
  function laniakeaPoint(p){var unit=LANIAKEA_REFERENCE_MPC*LANIAKEA_H;return [p[0]/unit,p[2]/unit,-p[1]/unit];}
  function laniakeaPathPoint(path,f){
    if(!path||!path.length)return [0,0,0];if(path.length===1)return path[0].slice(0,3);
    var lengths=[0],total=0;for(var i=1;i<path.length;i++){total+=Math.hypot(path[i][0]-path[i-1][0],path[i][1]-path[i-1][1],path[i][2]-path[i-1][2]);lengths.push(total);}
    var distance=clamp(Number.isFinite(f)?f:0,0,1)*total;
    for(var j=1;j<path.length;j++)if(lengths[j]>=distance){var t=(distance-lengths[j-1])/Math.max(1e-12,lengths[j]-lengths[j-1]);return [0,1,2].map(function(k){return path[j-1][k]+(path[j][k]-path[j-1][k])*t;});}
    return path[path.length-1].slice(0,3);
  }
  function laniakeaRoutePoint(f){return laniakeaPoint(laniakeaPathPoint(LANIAKEA_DATA.homePath,f));}
