  function virgoDistance(dm){return Math.pow(10,(dm-25)/5);}
  function virgoPoint(l,b,d){var lon=l*Math.PI/180,lat=b*Math.PI/180,r=d/VIRGO_REFERENCE_MPC;return [r*Math.cos(lat)*Math.cos(lon),r*Math.sin(lat),-r*Math.cos(lat)*Math.sin(lon)];}
