  function reefRingArea(ring){var area=0;for(var i=0,j=ring.length-1;i<ring.length;j=i++)area+=ring[j][0]*ring[i][1]-ring[i][0]*ring[j][1];return area/2;}
  function reefContains(ring,point){var inside=false;for(var i=0,j=ring.length-1;i<ring.length;j=i++){var a=ring[i],b=ring[j];if((a[1]>point[1])!==(b[1]>point[1])&&point[0]<(b[0]-a[0])*(point[1]-a[1])/(b[1]-a[1])+a[0])inside=!inside;}return inside;}
  function reefPolygons(rings){
    var clean=rings.map(function(ring){var r=ring.slice();if(r.length>1&&r[0][0]===r[r.length-1][0]&&r[0][1]===r[r.length-1][1])r.pop();return r;}).filter(function(r){return r.length>=3&&Math.abs(reefRingArea(r))>1e-12;});
    var shells=clean.filter(function(r){return reefRingArea(r)<0;}).map(function(r){return {outer:r,holes:[]};});
    clean.filter(function(r){return reefRingArea(r)>0;}).forEach(function(hole){var parent=null,area=Infinity;shells.forEach(function(shell){var a=Math.abs(reefRingArea(shell.outer));if(a<area&&reefContains(shell.outer,hole[0])){parent=shell;area=a;}});if(parent)parent.holes.push(hole);});return shells;
  }
  function validReefMap(data){
    if(!data||data.version!==1||!Array.isArray(data.features)||data.features.length<1000||data.features.length>6500)return false;
    var count=0;return data.features.every(function(f){return f&&typeof f.id==='number'&&['Reef','Mainland','Island','Cay'].indexOf(f.type)>=0&&Array.isArray(f.rings)&&f.rings.every(function(r){return Array.isArray(r)&&r.length>=4&&r.every(function(p){count++;return count<180000&&Array.isArray(p)&&p.length===2&&typeof p[0]==='number'&&typeof p[1]==='number'&&isFinite(p[0])&&isFinite(p[1])&&p[0]>=141&&p[0]<=154&&p[1]>=-25.5&&p[1]<=-9.5;});});});
  }
  function reefScaleStep(metresPerPixel){if(typeof metresPerPixel!=='number'||!isFinite(metresPerPixel)||metresPerPixel<=0)return 0;var target=metresPerPixel*110,power=Math.pow(10,Math.floor(Math.log(target)/Math.LN10)),ratio=target/power;return (ratio>=5?5:ratio>=2?2:1)*power;}
