    if(id==='alpha-cen-dist')return [{id:'cen-overview',centauriSite:true,marker:false,at:centauriPoint('cen-overview',0).at,view:centauriPoint('cen-overview',0).view,zoom:centauriPoint('cen-overview',0).zoom,label:S('atlas_centauri_overview',"Across interstellar space"),body:S('atlas_centauri_overview_body',"The reference joins the Sun to the A/B binary’s centre of mass across a rounded 4.1 × 10¹⁶ metres, about 4.33 light-years. The closest individual star, Proxima Centauri, lies slightly nearer. Enlarged position guides locate stars whose physical discs are far below one pixel here."),source:"https://arxiv.org/abs/1611.03495"},
{id:'cen-system',centauriSite:true,marker:false,at:centauriPoint('cen-system',0).at,view:centauriPoint('cen-system',0).view,zoom:centauriPoint('cen-system',0).zoom,label:S('atlas_centauri_system',"Three stellar neighbours"),body:S('atlas_centauri_system_body',"Alpha Centauri A and B form a close binary. Proxima is their distant red-dwarf companion, about 12,947 astronomical units from the pair in the adopted reference. The three sides of this teaching triangle retain their stated lengths; its orientation is composed, rather than a reconstruction of their positions on the sky."),source:"https://arxiv.org/abs/1611.03495"},
{id:'cen-binary',centauriSite:true,marker:false,at:centauriPoint('cen-binary',0).at,view:centauriPoint('cen-binary',0).view,zoom:centauriPoint('cen-binary',0).zoom,label:S('atlas_centauri_binary',"The A/B binary"),body:S('atlas_centauri_binary_body',"Move through a Keplerian orbit around the shared centre of mass. A is more massive and follows the smaller ellipse. The relative orbit has a semimajor axis of 23.54 AU and eccentricity 0.5208; the stars are about 11.28 AU apart at closest approach and 35.81 AU at their widest separation. Position guides are enlarged."),source:"https://arxiv.org/abs/1611.03495"},
{id:'cen-a',centauriSite:true,marker:false,at:centauriPoint('cen-a',0).at,view:centauriPoint('cen-a',0).view,zoom:centauriPoint('cen-a',0).zoom,label:S('atlas_centauri_a',"Alpha Centauri A"),body:S('atlas_centauri_a_body',"Approach the larger, Sun-like star. Its adopted diameter is about 1.70 million kilometres, using an interferometric radius of 1.2234 nominal solar radii. The camera follows A as the orbital phase changes. The visible surface pattern, colour and spots are illustrative, not resolved images of this star."),source:"https://arxiv.org/abs/1611.03495"},
{id:'cen-b',centauriSite:true,marker:false,at:centauriPoint('cen-b',0).at,view:centauriPoint('cen-b',0).view,zoom:centauriPoint('cen-b',0).zoom,label:S('atlas_centauri_b',"Alpha Centauri B"),body:S('atlas_centauri_b_body',"The smaller member of the close binary is a cooler K-type star. Its adopted diameter is about 1.20 million kilometres, or 0.8632 nominal solar diameters. It traces the larger orbit about the pair’s centre of mass. Surface contrast and warm colour are illustrative."),source:"https://arxiv.org/abs/1611.03495"},
{id:'cen-proxima',centauriSite:true,marker:false,at:centauriPoint('cen-proxima',0).at,view:centauriPoint('cen-proxima',0).view,zoom:centauriPoint('cen-proxima',0).zoom,label:S('atlas_centauri_proxima',"Proxima Centauri"),body:S('atlas_centauri_proxima_body',"This red dwarf is the nearest individual star to the Sun, about 4.24 light-years away. Its adopted diameter here is about 215,000 kilometres, using the empirical 0.1542-solar-radius estimate adopted by the cited study. Other radius estimates differ. Its wide motion around A/B is held fixed while you explore the binary’s much shorter orbit."),source:"https://arxiv.org/abs/1611.03495"},
{id:'cen-sun',centauriSite:true,marker:false,at:centauriPoint('cen-sun',0).at,view:centauriPoint('cen-sun',0).view,zoom:centauriPoint('cen-sun',0).zoom,label:S('atlas_centauri_sun',"Return to the Sun"),body:S('atlas_centauri_sun_body',"Approach the Sun at the near end of the reference line. Its 1.392-million-kilometre catalogue diameter stays on exactly the same scale as all three distant stars. The camera makes the enormous change in viewing distance; it does not enlarge the stellar bodies."),source:"https://arxiv.org/abs/1611.03495"}];
    if(id==='au')return [{id:'au-overview',auSite:true,marker:false,at:auPoint('au-overview').at,view:auPoint('au-overview').view,zoom:auPoint('au-overview').zoom,label:S('atlas_au_overview',"The full astronomical unit"),body:S('atlas_au_overview_body',"The line joins the centres of the Sun and Earth across a rounded 149.6 million km reference. The Sun spans about one hundredth of this gap; Earth is smaller than a pixel in this wide view. The small location guides are enlarged, while both bodies keep their physical diameters."),source:"https://science.nasa.gov/earth/facts/"},
{id:'au-sun',auSite:true,marker:false,at:auPoint('au-sun').at,view:auPoint('au-sun').view,zoom:auPoint('au-sun').zoom,label:S('atlas_au_sun',"Solar photosphere"),body:S('atlas_au_sun_body',"Approach the Sun’s visible surface. Fine granulation, darker sunspots and gradual darkening toward the limb suggest the photosphere’s texture. The granular scale is about 1,000 km; contrast, colour, activity and the faint surrounding halo are illustrative."),source:"https://solarscience.msfc.nasa.gov/surface.shtml"},
{id:'au-midway',auSite:true,marker:false,at:auPoint('au-midway').at,view:auPoint('au-midway').view,zoom:auPoint('au-midway').zoom,label:S('atlas_au_midway',"Halfway across"),body:S('atlas_au_midway_body',"The selected reference point lies 74.8 million km from either centre. Light crosses either half in about 4 minutes 10 seconds. Orbit this point to see how small both bodies appear beside the space between them."),source:"https://science.nasa.gov/earth/facts/"},
{id:'au-approach',auSite:true,marker:false,at:auPoint('au-approach').at,view:auPoint('au-approach').view,zoom:auPoint('au-approach').zoom,label:S('atlas_au_approach',"Approach Earth"),body:S('atlas_au_approach_body',"Move the camera close enough to resolve Earth against the gap. Its mean diameter remains 12,742 km, about 1/11,741 of the reference distance. The direction of sunlight stays fixed toward the Sun as you orbit."),source:"https://science.nasa.gov/earth/facts/"},
{id:'au-earth',auSite:true,marker:false,at:auPoint('au-earth').at,view:auPoint('au-earth').view,zoom:auPoint('au-earth').zoom,label:S('atlas_au_earth',"Earth in sunlight"),body:S('atlas_au_earth_body',"Look toward Earth from its sunlit side. NASA’s Blue Marble imagery supplies the surface colours. The globe and its thin atmospheric glow keep their dimensions as the camera approaches; the surface is a composite rather than current weather."),source:"https://science.nasa.gov/earth/facts/"},
{id:'au-terminator',auSite:true,marker:false,at:auPoint('au-terminator').at,view:auPoint('au-terminator').view,zoom:auPoint('au-terminator').zoom,label:S('atlas_au_terminator',"Across the terminator"),body:S('atlas_au_terminator_body',"Orbit toward the boundary between day and night. The same Sun direction lights the globe throughout the scene. NASA’s 2016 Black Marble composite becomes visible on the dark side, with a subtle illuminated atmospheric rim."),source:"https://science.nasa.gov/earth/facts/"}].concat(Array.from({length:101},function(_,n){var p=auPoint('au-passage-'+n);return {id:'au-passage-'+n,auSite:true,auSample:true,marker:false,at:p.at,view:p.view,zoom:p.zoom,label:S('atlas_au_passage_label',"Across one astronomical unit · {percent}%",{percent:n}),body:S('atlas_au_passage_body',"The marker selects a point along the centre-to-centre reference distance. The camera orbits that point and moves closer near the endpoints. Distances and light times describe the fixed diagram; the camera has no physical travel speed."),source:"https://science.nasa.gov/earth/facts/"};}));
    if(id==='human')return HUMAN_STUDY_SITES.map(function(site){return Object.assign({humanStudySite:true,marker:false,label:S('atlas_human_'+site.key,site.label),body:S('atlas_human_'+site.key+'_body',site.body),source:HUMAN_STUDY_SOURCE,id:site.id},humanStudyPoint(site.id));}).concat(Array.from({length:101},function(_,n){return Object.assign({id:'human-height-'+n,humanStudySite:true,humanHeightSample:true,marker:false,label:S('atlas_human_level','Height guide · {percent}%',{percent:n}),body:S('atlas_human_level_body','The gold guide marks a fraction of the figure’s full stature, measured vertically from the ground. Its centimetre readout updates when you change the person’s height. The figure keeps the same proportions throughout.'),source:HUMAN_STUDY_SOURCE},humanStudyPoint('human-height-'+n));}));
