    if(id==='coma-dist')return COMA_SITES.map(function(site){return Object.assign({comaSite:true,marker:false,label:S('atlas_coma_'+site.key,site.label),body:S('atlas_coma_'+site.key+'_body',site.body),source:site.source,id:site.id},comaPoint(site.id));}).concat(Array.from({length:101},function(_,n){return Object.assign({id:'coma-passage-'+n,comaSite:true,comaSample:true,marker:false,label:S('atlas_coma_passage','The crossing · {percent}%',{percent:n}),body:S('atlas_coma_passage_body','Move a reference point along the full distance. The virtual camera approaches either endpoint to reveal its structure while all galaxy dimensions stay fixed. This is a static distance illustration, without an elapsed travel time.'),source:'https://www.chandra.harvard.edu/photo/2019/coma/'},comaPoint('coma-passage-'+n));}));
    if(id==='andromeda-dist')return [{id:'andromeda-overview',andromedaSite:true,marker:false,at:andromedaPoint('andromeda-overview').at,view:andromedaPoint('andromeda-overview').view,zoom:andromedaPoint('andromeda-overview').zoom,label:S('atlas_andromeda_overview',"The full crossing"),body:S('atlas_andromeda_overview_body',"Our Solar System and Andromeda’s centre are about 2.54 million light-years apart. Both galaxies keep their adopted physical diameters, so they look small beside the gap. The line is a distance guide, with a small tick every 100,000 light-years."),source:"https://science.nasa.gov/universe/exoplanets/our-milky-way-galaxy-how-big-is-space/"},
{id:'andromeda-home',andromedaSite:true,marker:false,at:andromedaPoint('andromeda-home').at,view:andromedaPoint('andromeda-home').view,zoom:andromedaPoint('andromeda-home').zoom,label:S('atlas_andromeda_home',"Our place in the disc"),body:S('atlas_andromeda_home_body',"Begin at our Solar System, away from the Milky Way’s centre. The adopted galactic disc is about 100,000 light-years across. Its warm central bar, blue spiral light and intervening dust are a procedural illustration. The gold local marker is enlarged to locate our Sun."),source:"https://science.nasa.gov/universe/exoplanets/our-milky-way-galaxy-how-big-is-space/"},
{id:'andromeda-departure',andromedaSite:true,marker:false,at:andromedaPoint('andromeda-departure').at,view:andromedaPoint('andromeda-departure').view,zoom:andromedaPoint('andromeda-departure').zoom,label:S('atlas_andromeda_departure',"Beyond our galaxy"),body:S('atlas_andromeda_departure_body',"Move about 89,000 light-years along the sightline to Andromeda. This direction leaves the Milky Way’s disc at an angle; the journey does not follow its central plane. The camera is an inspection tool, without a claimed travel speed."),source:"https://science.nasa.gov/universe/exoplanets/our-milky-way-galaxy-how-big-is-space/"},
{id:'andromeda-midway',andromedaSite:true,marker:false,at:andromedaPoint('andromeda-midway').at,view:andromedaPoint('andromeda-midway').view,zoom:andromedaPoint('andromeda-midway').zoom,label:S('atlas_andromeda_midway',"The intergalactic gap"),body:S('atlas_andromeda_midway_body',"The midpoint lies about 1.27 million light-years from either endpoint. The small angular sizes reveal how much space separates the galaxies. The surrounding intergalactic medium is too faint for this illustration; the empty-looking gap is not a claim of perfect vacuum."),source:"https://science.nasa.gov/universe/exoplanets/our-milky-way-galaxy-how-big-is-space/"},
{id:'andromeda-arrival',andromedaSite:true,marker:false,at:andromedaPoint('andromeda-arrival').at,view:andromedaPoint('andromeda-arrival').view,zoom:andromedaPoint('andromeda-arrival').zoom,label:S('atlas_andromeda_arrival',"Approach Andromeda"),body:S('atlas_andromeda_arrival_body',"Approach to about 89,000 light-years from Andromeda’s centre along our sightline. Its highly inclined disc reveals a warm bulge and dark dust lanes. This view illustrates its shape and orientation; it does not predict the galaxy’s future motion."),source:"https://science.nasa.gov/universe/exoplanets/our-milky-way-galaxy-how-big-is-space/"},
{id:'andromeda-disc',andromedaSite:true,marker:false,at:andromedaPoint('andromeda-disc').at,view:andromedaPoint('andromeda-disc').view,zoom:andromedaPoint('andromeda-disc').zoom,label:S('atlas_andromeda_disc',"Andromeda from above"),body:S('atlas_andromeda_disc_body',"Orbit above Andromeda’s disc to see its ring of young stars and dust near a 10-kiloparsec radius. The bright disc fades into a larger stellar extent. The adopted 220,000-light-year diameter is an approximate outer reference; galaxies have no sharp surface."),source:"https://science.nasa.gov/photojournal/the-infrared-face-of-the-andromeda-galaxy/"}].concat(Array.from({length:101},function(_,n){var p=andromedaPoint('andromeda-passage-'+n);return {id:'andromeda-passage-'+n,andromedaSite:true,andromedaSample:true,marker:false,at:p.at,view:p.view,zoom:p.zoom,label:S('atlas_andromeda_passage_label',"Intergalactic crossing · {percent}%",{percent:n}),body:S('atlas_andromeda_passage_body',"Move through the reference gap while the galaxies keep their physical sizes and positions. The camera pulls closer near either endpoint to reveal structure. The position is a distance along a static diagram, not elapsed physical travel time."),source:"https://science.nasa.gov/universe/exoplanets/our-milky-way-galaxy-how-big-is-space/"};}));
    if(id==='universe')return [{id:'universe-overview',universeSite:true,marker:false,at:universeEpochPoint(universeViewEpoch('universe-overview')),viewAim:[0,0,0],view:[0.8,0.42,1],zoom:1,label:S('atlas_universe_overview',"The cosmic cutaway"),body:S('atlas_universe_overview_body',"Orbit the light reaching our observer today. Radial positions use present-day comoving distances, while farther-out layers depict earlier epochs. The galaxy web and microwave colours are composed illustrations, not an observed all-sky map."),source:"https://arxiv.org/abs/1807.06209"},
{id:'universe-near',universeSite:true,marker:false,at:universeEpochPoint(universeViewEpoch('universe-near')),view:[0.45,0.4,1],zoom:2.8,label:S('atlas_universe_near',"Evolving galaxies"),body:S('atlas_universe_near_body',"At redshift 1, this model gives a cosmic age of about 5.84 billion years. The light has travelled for about 7.95 billion years, while expansion makes the present-day comoving distance about 11.09 billion light-years. The enlarged galaxy marks illustrate structure."),source:"https://arxiv.org/abs/1807.06209"},
{id:'universe-growth',universeSite:true,marker:false,at:universeEpochPoint(universeViewEpoch('universe-growth')),view:[0.5,0.3,1],zoom:2.5,label:S('atlas_universe_growth',"Early galaxy growth"),body:S('atlas_universe_growth_body',"Look to redshift 3, when the model universe was about 2.14 billion years old. Galaxies were assembling and forming stars. The guide lies about 21.22 billion light-years away in present-day comoving distance; its schematic structures do not identify real galaxies."),source:"https://arxiv.org/abs/1807.06209"},
{id:'universe-dawn',universeSite:true,marker:false,at:universeEpochPoint(universeViewEpoch('universe-dawn')),view:[0.1,0.35,1],zoom:2.3,label:S('atlas_universe_dawn',"Reionization era"),body:S('atlas_universe_dawn_body',"At redshift 8, the model universe was about 636 million years old. Early sources were helping to ionize intergalactic hydrogen. The sparse illustrated galaxy layer fades outward into a darker region. Galaxies also existed beyond this illustrated layer; the fade is a visual guide, not a measured spherical boundary."),source:"https://arxiv.org/abs/1807.06209"},
{id:'universe-cmb',universeSite:true,marker:false,at:universeEpochPoint(universeViewEpoch('universe-cmb')),view:[-0.3,0.25,1],zoom:2.8,label:S('atlas_universe_cmb',"The oldest light"),body:S('atlas_universe_cmb_body',"The cosmic microwave background is light that last scattered when the universe became transparent. This simplified model at redshift 1089 gives an age of about 372,000 years and a comoving distance of 45.22 billion light-years. The coloured patches are illustrative; this is not a Planck temperature map."),source:"https://arxiv.org/abs/1807.06209"},
{id:'universe-horizon',universeSite:true,marker:false,at:universeEpochPoint(universeViewEpoch('universe-horizon')),viewAim:[0,0,0],view:[0.8,0.3,1],zoom:1.2,label:S('atlas_universe_horizon',"Beyond the oldest light"),body:S('atlas_universe_horizon_body',"The particle horizon is the farthest comoving distance a signal could have covered since the model’s beginning. Here its radius is about 46.13 billion light-years, just beyond the microwave-background surface. It is not a wall, an event horizon, or an edge of space."),source:"https://arxiv.org/abs/1807.06209"}].concat(UNIVERSE_EPOCHS.map(function(epoch,n){return {id:'universe-slice-'+n,universeSite:true,universeSample:true,marker:false,at:universeEpochPoint(epoch),viewAim:[0,0,0],view:[.8,.42,1],zoom:1.4,label:S('atlas_universe_sample_label',"Lookback journey · z {z}",{z:epoch.z.toFixed(epoch.z<10?2:0)}),body:S('atlas_universe_sample_body',"Explore a calculated distance shell. The readouts connect redshift, cosmic age and present-day comoving distance. The observer remains fixed at the centre; the camera is inspecting a diagram of light reaching that observer."),source:'https://arxiv.org/abs/astro-ph/9905116'};}));
    if(id==='laniakea')return [{id:'laniakea-overview',laniakeaSite:true,marker:false,at:LANIAKEA_CENTER,view:[-0.42,0.32,1],zoom:1,label:S('atlas_laniakea_overview',"The whole flow basin"),body:S('atlas_laniakea_overview_body',"Orbit an irregular watershed reconstructed from the Cosmicflows-4 data. Gold lines follow the inferred peculiar-velocity field after cosmic expansion is removed. The boundary is a model result, not a solid enclosure."),source:"https://arxiv.org/abs/2305.02339"},
{id:'laniakea-boundary',laniakeaSite:true,marker:false,at:LANIAKEA_CENTER,view:[0.7,0.32,0.9],zoom:1.05,label:S('atlas_laniakea_boundary',"Read the watershed"),body:S('atlas_laniakea_boundary_body',"Brighten the basin surface and quiet the flow lines. This smoothed surface is extracted from the published 2023 basin grid. Its shape is limited by the grid resolution and the reconstruction method."),source:"https://arxiv.org/abs/2305.02339"},
{id:'laniakea-plane',laniakeaSite:true,marker:false,at:LANIAKEA_CENTER,view:[0,1,0.01],zoom:1.05,label:S('atlas_laniakea_plane',"Above the cosmic plane"),body:S('atlas_laniakea_plane_body',"Look down on the supergalactic coordinate plane. Each grid interval is 25 megaparsecs. This reference plane cuts through a three-dimensional basin; it is not a physical sheet."),source:"https://arxiv.org/abs/2305.02339"},
{id:'laniakea-home',laniakeaSite:true,marker:false,at:laniakeaRoutePoint(0),view:[0.35,0.4,1],zoom:3.5,label:S('atlas_laniakea_home',"Start from our location"),body:S('atlas_laniakea_home_body',"The mint marker locates the Milky Way at the coordinate origin. Follow the mint streamline to see the direction of the reconstructed local flow. Markers and arrows are enlarged; the route is not a forecast of our galaxy’s future."),source:"https://arxiv.org/abs/2305.02339"},
{id:'laniakea-journey',laniakeaSite:true,marker:false,at:laniakeaRoutePoint(.5),view:[-0.35,0.32,1],zoom:4.5,label:S('atlas_laniakea_journey',"Along the local flow"),body:S('atlas_laniakea_journey_body',"Travel halfway along the displayed local streamline by path length. The fixed field guides this route through space. The apparent pace of the gold pulses is an illustration, not a physical clock."),source:"https://arxiv.org/abs/2305.02339"},
{id:'laniakea-convergence',laniakeaSite:true,marker:false,at:laniakeaRoutePoint(1),view:[0.4,0.35,1],zoom:4,label:S('atlas_laniakea_convergence',"Where the flow gathers"),body:S('atlas_laniakea_convergence_body',"Approach the endpoint of the local streamline in this reconstruction. Nearby lines gather toward the same region. This marks a convergence of the inferred field, not a single object or a point containing the supercluster’s mass."),source:"https://arxiv.org/abs/2305.02339"}];
