      [[0,38.4,113,.25],[0,-38.4,113,.25],[56.8,0,.25,77],[-56.8,0,.25,77]].forEach(function(b){var m=box(stadium,boards,b[0]*u,.45*u,b[1]*u,b[2]*u,.9*u,b[3]*u);m.castShadow=false;m.name='stadium LED boards';});
