      function chooseDetail(detail,force,preserveViewport){
        setNebulaInside(false);
        if(detail.night&&planetImagery.earthNight!=='ready')return;
        if((detail.surface||detail.terrain)&&(planetImagery.id!==focusId||planetImagery.status!=='ready'))return;
        stopJourney();
        if(detail.night){setEarthLights(true);setSunAngle(155);}
        if(detail.datum)setMeasure(true);
        if(detailId===detail.id&&!force){setDetailId('');setInspectionZoom(1);return;}
        setDetailId(detail.id);setShowDetails(true);setNeighbors(false);setInspectionZoom(detail.zoom||(focusId==='dna'?2.2:1.8));
        if(detail.cutaway!==undefined)setCutaway(detail.cutaway);if(focusId==='pollen'&&detail.id==='pollen-tube')setPollenGrowth(function(g){return Math.max(.25,g);});
        if(focusId==='hydrogen'){setHydrogenView(detail.id==='density'?'section':'cloud');setCutaway(false);}
        if(focusId==='nucleus'){setNucleusView(detail.id==='core'?'section':'whole');if(detail.id==='core')setNucleusDepth(50);setCutaway(false);}
        if(detail.reveal!==undefined)setNebulaReveal(detail.reveal);
        if(force&&atlasRef.current)atlasRef.current.approach();
        say(detail.label+'. '+detail.body);
        var cv=atlasCanvasRef.current;
        if(cv&&!preserveViewport){var rect=cv.getBoundingClientRect();if(rect.top< -40||rect.bottom>window.innerHeight+40)cv.scrollIntoView({block:'center',behavior:reduceMotion?'auto':'smooth'});}
      }
