            xs = [c.x - dx, c.x + dx].filter(function (v) { return v > 40 && v < cssW - 40; }).sort(function (a, b) { return Math.abs(a - cssW / 2) - Math.abs(b - cssW / 2); });
            if (xs.length) return { x: xs[0], y: top, below: true };
